INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('easydev991/SwiftUI-WorkoutApp/localization', 'localization', 'easydev991', 'SwiftUI-WorkoutApp', 'community', 'localization easydev991 SwiftUI-WorkoutApp community Street Workout 本地化是一个利用AI智能代理工具的iOS项目，用于提高开发效率 Street Workout ローカライズはAIエージェントを使用したiOSプロジェクトで、開発効率を向上させる 스트리트 워크아웃 지역화는 AI 에이전트를 사용한 iOS 프로젝트로 개발 효율을 향상시킵니다 Street Workout utiliza herramientas de localización para ofrecer una mejor experiencia al usuario en iOS Street Workout utilise des outils de localisation pour offrir une meilleure expérience utilisateur sur iOS Street Workout nutzt Lokalisierungstools, um eine bessere Benutzererfahrung auf iOS zu bieten O Street Workout Площадки é um pet-projeto para iOS que demonstra a importância da localização em aplicativos móveis, utilizando React e Node.js Street Workout Площадки - это пет-проект для iOS, демонстрирующий важность локализации в мобильных приложениях, с использованием React и Node.js Street Workout Площадки هو مشروع تجريبي لمنصة iOS يبرز أهمية التدويل في التطبيقات الجوال، مستخدماً React و Node.js Street Workout Площадки (пет-проект, iOS) AI智能代理工具 Street Workout 本地化 如何使用AI工具 React开发教程 Node.js自动化部署 Python数据处理 iOS开发框架 Street Workout Площадки (пет-проект, iOS)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ComposioHQ/awesome-claude-skills', 'official', 'ComposioHQ', 'awesome-claude-skills', 'ComposioHQ/awesome-claude-skills', 'awesome-claude-skills', 41178, 4088, 0, '2026-03-06T04:41:28Z', '2026-03-06T04:47:42.237Z', 'a9c479209bfcd315bca195e3eea46fe16362137280b3e8645b9713b25e732ded', '{"id":"ComposioHQ/awesome-claude-skills","name":"awesome-claude-skills","description":{"en":"awesome-claude-skills provides a curated list of resources and tools for customizing Claude AI workflows, benefiting developers and automation specialists. It supports various technologies, including gemini-cli, mcp, and rube.","zh":"Awesome Claude Skills 是一个精心策划的资源集合，专门为开发人员提供Claude Skills、工具和工作流自动化解决方案。包含MCP协议实现、Composio集成、Cursor编辑器扩展等专业技术资源","ja":"Awesome Claude Skills は開発者向けに厳選されたClaude SkillsとAIエージェントカスタマイズリソースです。MCPプロトコル、Composio連携、Cursorエディタ拡張などの技術ツールとワークフロー自動化ソリューションを提供","ko":"Awesome Claude Skills는 개발자를 위한 Claude Skills 및 AI 에이전트 커스터마이징 리소스의 큐레이티드 목록입니다. MCP 프로토콜, Composio 연동, Cursor 편집기 확장 등의 기술 도구와 워크플로우 자동화 솔루션을 포함","es":"awesome-claude-skills es una colección curada de recursos técnicos para personalizar workflows de Claude AI. Incluye herramientas MCP, integraciones Comosio, automatización con Claude Code y ejemplos de agentes IA.","fr":"awesome-claude-skills est une collection organisée de ressources techniques pour personnaliser les workflows Claude AI. Comprend outils MCP, intégrations Comosio, automatisation avec Claude Code et exemples d''agents IA.","de":"awesome-claude-skills ist eine kuratierte Sammlung technischer Ressourcen zur Anpassung von Claude AI Workflows. Enthält MCP Tools, Comosio Integrationen, Automatisierung mit Claude Code und KI Agenten Beispiele.","pt":"O awesome-claude-skills é uma lista curada de recursos e ferramentas para personalizar fluxos de trabalho de IA com Claude","ru":"awesome-claude-skills - это отобранная коллекция ресурсов и инструментов для кастомизации рабочих процессов ИИ с помощью Claude","ar":"awesome-claude-skills هو قائمة مركبة من الموارد والأدوات لتعزيز سير العمل التلقائي للوكلاء الذكاء الاصطناعي مع Claude"},"seo":{"title":{"en":"awesome-claude-skills: Customizable AI Workflows Setup Gu...","zh":"Awesome Claude Skills 设置指南：自定义AI工作流","ja":"Awesome Claude Skills セットアップガイド：AIエージェントカスタマイズ","ko":"Awesome Claude Skills 설정 가이드: 클로드 AI 워크플로우 커스터마이징","es":"Guía de awesome-claude-skills: Lista de recursos para Cla...","fr":"Guide awesome-claude-skills: Ressources pour workflows Cl...","de":"awesome-claude-skills: Best Practices für Claude AI Agenten","pt":"Guia de Configuração do awesome-claude-skills para Automa...","ru":"Настройка awesome-claude-skills для Автоматизации Работоч...","ar":"دليل إعداد awesome-claude-skills لتحسين سير العمل التلقائ..."},"description":{"en":"Unlock the full potential of Claude AI with awesome-claude-skills. Discover curated resources, tools, and workflows to automate tasks. Get started now!","zh":"Awesome Claude Skills 精选集，包含Claude Skills、工具和资源。学习使用MCP、Composio、Cursor等工具自定义Claude AI工作流和自动化代理技能开发","ja":"Awesome Claude Skills 厳選リストでAIエージェントをカスタマイズ。MCP、Composio、Cursorなどを使用したClaude AIワークフロー自動化の開発リソースとツールを紹介","ko":"Awesome Claude Skills 큐레이티드 목록으로 Claude AI 워크플로우 커스터마이징. MCP, Composio, Cursor 등을 활용한 에이전트 스킬 개발 및 자동화 도구와 리소스 제공","es":"Lista curada de Skills de Claude AI, herramientas MCP, Comosio y automatización de workflows. Recursos técnicos para desarrolladores de agentes de IA.","fr":"Liste organisée de compétences Claude AI, outils MCP, Comosio et automatisation de workflows. Ressources techniques pour développeurs d''agents IA.","de":"Kuratiere Liste von Claude AI Skills, MCP Tools, Comosio und Workflow-Automatisierung. Technische Ressourcen für KI Agenten Entwickler.","pt":"Aprenda a configurar o awesome-claude-skills para personalizar fluxos de trabalho de IA com ferramentas como Claude Code e Gemini-CLI","ru":"Узнайте, как настроить awesome-claude-skills для кастомизации рабочих процессов ИИ с помощью инструментов seperti Claude Code и Gemini-CLI","ar":"تعرف على كيفية إعداد awesome-claude-skills لتعزيز سير العمل التلقائي للوكلاء الذكاء الاصطناعي باستخدام أدوات مثل Claude Code وGemini-CLI"},"definition":{"en":"awesome-claude-skills is a collection of curated resources, tools, and workflows for customizing and automating Claude AI tasks, utilizing technologies like codex and composio.","zh":"Awesome Claude Skills 是一个开发者资源集合，专门提供Claude AI技能定制、工作流自动化和代理开发工具。包含MCP协议实现、Composio集成、Cursor编辑器扩展等技术组件，帮助开发者构建高效的AI代理工作流","ja":"Awesome Claude Skills はClaude AIのスキルカスタマイズ、ワークフロー自動化、エージェント開発のための開発者リソース集です。MCPプロトコル実装、Composio連携、Cursorエディタ拡張などの技術コンポーネントを含み、効率的なAIエージェントワークフロー構築を支援","ko":"Awesome Claude Skills는 Claude AI 스킬 커스터마이징, 워크플로우 자동화, 에이전트 개발을 위한 개발자 리소스 컬렉션입니다. MCP 프로토콜 구현, Composio 연동, Cursor 편집기 확장 등의 기술 컴포넌트를 포함하여 효율적인 AI 에이전트 워크플로우 구축 지원","es":"awesome-claude-skills es un repositorio curado de recursos para desarrolladores que trabajan con Claude AI. Proporciona herramientas MCP, integraciones Comosio, ejemplos de automatización de workflows y referencias técnicas para crear agentes de IA personalizados.","fr":"awesome-claude-skills est un dépôt organisé de ressources pour développeurs travaillant avec Claude AI. Fournit outils MCP, intégrations Comosio, exemples d''automatisation de workflows et références techniques pour créer des agents IA personnalisés.","de":"awesome-claude-skills ist ein kuratiertes Repository mit Ressourcen für Entwickler, die mit Claude AI arbeiten. Bietet MCP Tools, Comosio Integrationen, Workflow-Automatisierungsbeispiele und technische Referenzen für KI Agenten Entwicklung.","pt":"O que é awesome-claude-skills? É uma lista de recursos para personalizar fluxos de trabalho de IA com Claude","ru":"Что такое awesome-claude-skills? Это коллекция ресурсов для кастомизации рабочих процессов ИИ с помощью Claude","ar":"ما هو awesome-claude-skills؟ هو قائمة من الموارد لتعزيز سير العمل التلقائي للوكلاء الذكاء الاصطناعي مع Claude"},"features":{"en":["Supports automation using gemini-cli and mcp","Utilizes codex for customizable AI workflows","Integrates with composio for enhanced workflow automation","Includes resources for antigravity and cursor customization","Compatible with SaaS applications and rube technology"],"zh":["MCP（Model Context Protocol）协议实现和工具集成","Composio平台连接与SaaS服务自动化工作流","Cursor编辑器扩展支持代码生成和AI辅助开发","Claude Code代码生成和代码优化技能资源","Antigravity和Rube Goldberg自动化工作流示例","Gemini CLI工具集成和命令行界面自动化"],"ja":["MCP（Model Context Protocol）プロトコル実装とツール連携","Composioプラットフォーム接続とSaaSサービス自動化ワークフロー","Cursorエディタ拡張によるコード生成とAI支援開発","Claude Codeコード生成とコード最適化スキルリソース","AntigravityとRube Goldberg自動化ワークフロー事例","Gemini CLIツール統合とコマンドラインインターフェース自動化"],"ko":["MCP(Model Context Protocol) 프로토콜 구현 및 도구 통합","Composio 플랫폼 연결과 SaaS 서비스 자동화 워크플로우","Cursor 편집기 확장 지원 코드 생성 및 AI 지원 개발","Claude Code 코드 생성과 코드 최적화 스킬 리소스","Antigravity와 Rube Goldberg 자동화 워크플로우 예시","Gemini CLI 도구 통합 및 커맨드라인 인터페이스 자동화"],"es":["Colección de herramientas MCP (Model Context Protocol) para Claude","Integraciones Comosio para conexiones SaaS y APIs","Ejemplos de automatización de workflows con Claude Code","Recursos para desarrollo de agentes IA personalizados","Herramientas CLI como gemini-cli y cursor","Técnicas de antigravity y Rube Goldberg automation"],"fr":["Collection d''outils MCP (Model Context Protocol) pour Claude","Intégrations Comosio pour connexions SaaS et APIs","Exemples d''automatisation de workflows avec Claude Code","Ressources pour développement d''agents IA personnalisés","Outils CLI comme gemini-cli et cursor","Techniques d''antigravity et automation Rube Goldberg"],"de":["Sammlung von MCP (Model Context Protocol) Tools für Claude","Comosio Integrationen für SaaS und API Verbindungen","Workflow-Automatisierungsbeispiele mit Claude Code","Ressourcen für Entwicklung individueller KI Agenten","CLI Tools wie gemini-cli und cursor","Antigravity und Rube Goldberg Automati